//! Submitter formMethod distinguishes missing overrides from invalid values.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://submitter-method.test/send><input id=area name=q value=Seed><input id=input type=submit name=i value=I><button id=button type=submit name=b value=B>Send</button></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://submitter-method.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn submitter_form_method_canonical_missing_invalid_and_exact_once_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var id of ['input','button']){var x=document.getElementById(id),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'formMethod');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get formMethod'||a.set.name!=='set formMethod'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'formMethod')||x.formMethod!=='')throw 'canonical missing';x.formMethod='';if(x.formMethod!=='get')throw 'present empty';x.removeAttribute('formmethod');if(x.formMethod!=='')throw 'missing again';var calls=0;x.formMethod={toString:function(){calls++;return 'PoSt';},valueOf:function(){throw 'hint';}};if(calls!==1||x.formMethod!=='post'||x.getAttributeNS(null,'formmethod')!=='PoSt')throw 'once post';x.formMethod='DIALOG';if(x.formMethod!=='dialog')throw 'dialog';x.formMethod=' post ';if(x.formMethod!=='get'||x.getAttributeNS(null,'formmethod')!==' post ')throw 'no trim';x.formMethod='A\ud800Z';if(x.formMethod!=='get'||x.getAttributeNS(null,'formmethod')!=='A\ud800Z')throw 'raw DOMString';x.formMethod=null;if(x.formMethod!=='get'||x.getAttributeNS(null,'formmethod')!=='null')throw 'null';x.formMethod=undefined;if(x.formMethod!=='get'||x.getAttributeNS(null,'formmethod')!=='undefined')throw 'undefined';}"#);}
#[test]
fn submitter_form_method_inert_exact_namespace_and_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var tag of ['input','button']){var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml',tag);x.setAttributeNS('urn:foreign','formmethod','post');x.setAttributeNS(null,'FORMMETHOD','post');if(x.formMethod!=='')throw 'missing exact namespace';x.formMethod='PoSt';var copy=x.cloneNode(false);copy.formMethod='DIALOG';if(x.formMethod!=='post'||copy.formMethod!=='dialog'||x.getAttributeNS(null,'formmethod')!=='PoSt')throw 'independent';x.removeAttributeNS(null,'formmethod');if(x.formMethod!=='')throw 'remove';}");}
#[test]
fn submitter_form_method_native_inheritance_override_and_dialog_refusal(){for id in ["input","button"]{let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let submit=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some(id)).unwrap();let l=crate::navigation::address("https://submitter-method.test/source",&crate::navigation::Location::home()).unwrap();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}');if(x.formMethod!=='')throw 'missing';"));assert!(matches!(f.submit_request(&d,owner,Some(submit),&l,&l).unwrap().request,crate::http::Request::FormPost{..}));for(raw,known,post)in[("GET","get",false),("PoSt","post",true),("invalid","get",false),(" post ","get",false)]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("x.formMethod='{raw}';if(x.formMethod!=='{known}')throw 'keyword';"));assert_eq!(matches!(f.submit_request(&d,owner,Some(submit),&l,&l).unwrap().request,crate::http::Request::FormPost{..}),post);}run(&mut d,&mut f,&mut p,"x.formMethod='DIALOG';if(x.formMethod!=='dialog')throw 'dialog reflection';");let before=format!("{:?}",d.nodes);assert!(f.submit_request(&d,owner,Some(submit),&l,&l).err().unwrap().contains("DIALOG is not implemented"));assert_eq!(format!("{:?}",d.nodes),before);assert!(matches!(f.submit_request(&d,owner,None,&l,&l).unwrap().request,crate::http::Request::FormPost{..}));}}

#[test]
fn submitter_form_method_brands_saved_authority_and_abrupt_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input','button']){var x=document.getElementById(id),other=document.getElementById(id==='input'?'button':'input'),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'formMethod'),calls=0;for(var bad of [{},document,document.body,document.getElementById('form'),other,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'get';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.formMethod={toString:function(){calls++;x.formMethod='get';return 'PoSt';}};if(calls!==1||x.formMethod!=='post')throw 'once conversion';var marker={};try{x.formMethod={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'abrupt missing';}catch(e){if(e!==marker)throw e;}if(x.formMethod!=='post'||x.getAttribute('data-side')!=='kept')throw 'abrupt atomicity';Object.defineProperty(P,'formMethod',{get:function(){return 'author';},configurable:true});a.set.call(x,'GET');if(x.formMethod!=='author'||a.get.call(x)!=='get')throw 'saved authority';Object.defineProperty(P,'formMethod',a);}");}
#[test]
fn submitter_form_method_captured_origin_precedes_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var input=document.getElementById('input'),button=document.getElementById('button'),a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'formMethod'),b=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLButtonElement.prototype,'formMethod'),calls=0;if(a.get.call(input)!==''||b.get.call(button)!=='')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-submitter-method.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(input);","b.get.call(button);","a.set.call(input,{toString:function(){calls++;return 'get';}});","b.set.call(button,{toString:function(){calls++;return 'post';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://submitter-method.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'foreign converted';a.set.call(input,'POST');b.set.call(button,'GET');if(input.formMethod!=='post'||button.formMethod!=='get')throw 'fresh recovery';");}
#[test]
fn submitter_form_method_resource_refusal_is_atomic_and_fresh_job_recovers(){for id in ["input","button"]{for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}');x.formMethod='post';"));let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.element_form_method_get(object,"formmethod",true).map(|_|())}else if id=="input"{bridge.input_form_method_set(object,&Value::String("growing-unknown-method-value".into()))}else{bridge.button_form_method_set(object,&Value::String("growing-unknown-method-value".into()))};assert!(result.is_err(),"id {id} getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.formMethod='GET';if(x.formMethod!=='get'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}}
#[test]
fn submitter_form_method_attribute_writers_observe_identity_and_dirty_editor(){for id in ["input","button"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}'),editor=document.getElementById('area');editor.value='Edited';x.formMethod='get';var attribute=x.getAttributeNodeNS(null,'formmethod'),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true}});"));let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for code in ["x.setAttribute('formmethod','POST');","x.setAttributeNS(null,'formmethod','POST');","attribute.value='POST';","attribute.nodeValue='POST';","attribute.textContent='POST';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.formMethod='get';watch.takeRecords();");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.formMethod!=='post'||x.getAttributeNodeNS(null,'formmethod')!==attribute||records.length!==1||records[0].oldValue!=='get'||records[0].attributeName!=='formmethod'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}}}
